from pathlib import Path
import json,collections
R=Path('/workspace/scratch/78b838bd97fc/mind-change-research/inquiry')
class Tree:
 def __init__(self,root):self.n=[{'id':1,'parent':None,'claim':root,'certificate':'Declared input, checked in the cited fixture.'}]
 def children(self,parent,rows):
  ids=[]
  for claim,cert in rows:
   i=len(self.n)+1;self.n.append({'id':i,'parent':parent,'claim':claim,'certificate':cert});ids.append(i)
  return ids
 def save(self,name,intent,start,context,synthesis,later,benefit,verdict):
  children=collections.defaultdict(list)
  for n in self.n:
   if n['parent']:children[n['parent']].append(n['id'])
  depth={1:0}
  for n in self.n[1:]:depth[n['id']]=depth[n['parent']]+1
  assert len(self.n)>=45 and max(depth.values())>=7 and all(len(x)>=3 for x in children.values())
  s=f'''Intended mind change: {intent}

Starting working judgment and concrete input: {start}

Original: ../sources/inquiry-ar.original.md and separate receipt, plus the loaded corruption protocol. Facts are verified first against the exact source and prior test receipts; the formal model premises below are explicit. No choice is presented as a necessary implication. This 8x search has {len(self.n)} numbered claims, {max(depth.values())} parent-child edges on its deepest path and three children at every expanded node. The certificates state the additional declared context needed for each implication. “Necessary” means necessary inside that context, not an unconditional claim about humans or all possible programs.

Declared context: {context}

Phase 1 — exploration

'''
  for n in self.n:
   parent='INPUT' if n['parent'] is None else 'R'+str(n['parent']);leaf='; BEDROCK: concrete logic/test under declared inputs' if n['id'] not in children else ''
   s+=f'[R{n["id"]}] Parent {parent}; NECESSARY/conditional on declared context{leaf}. {n["claim"]} Certificate: {n["certificate"]}\n\n'
  s+='Phase 2 — complete registry\n\n| ID | Parent | Depth | Classification / endpoint |\n|---|---|---:|---|\n'
  for n in self.n:s+=f'| R{n["id"]} | '+('input' if n['parent'] is None else 'R'+str(n['parent']))+f' | {depth[n["id"]]} | necessary within model; '+('expanded into '+', '.join('R'+str(x) for x in children[n['id']]) if n['id'] in children else 'logical/test bedrock; original claim and certificate above')+' |\n'
  s+='\nAll numbered exploration claims occur in the registry. No probability of empirical transfer is inferred from logical certainty. Foreclosures are those explicitly stated in the claims, not a blanket recommendation to discard other interpretations.\n\nPhase 3 — synthesis\n\n'+synthesis+'\n\nDistinct later application: '+later+'\n\nActual mind change: '+intent+' The actual outcome is the scoped later-operation result above; already known parent findings are not counted again.\nBenefit: '+benefit+'\nVerdict: '+verdict+'\nOrganization: The numbered tree preserves premise dependencies and separate leaf tests. Synthesis introduces no new result; choices and their observed use are outside the implication tree.\nNext attempts: Change one decisive premise; test a new scope without calling it a replication; retain unobserved human or historical effects as unresolved.\n'
  (R/name).write_text(s);(R/(name[:-3]+'-tree.json')).write_text(json.dumps({'nodes':self.n,'depth':depth,'max_edges':max(depth.values()),'children':dict(children)},indent=2)+'\n')
