d,e,f=t.children(a,[('The qualifying set W={p inD:S(p) and M(p)} contains1.','The parent supplies1 and1∈D.'),('The same p=1 does not satisfy strict U(p):0<p<1.','Declared strict predicate excludes its upper endpoint.'),('The joint witness occurs at D’s upper endpoint.','D’s greatest value is1 and parent witness is1.')])
g,h,i=t.children(d,[('A candidate filter that deletes every joint S-and-M case deletes1.','The policy Q is explicitly defined to remove all W before answering the existence query.'),('An existence query over the unfiltered D has answer yes.','A member1 of W is an existential certificate.'),('A source relation label cannot make this stipulated witness disappear.','The formal predicates and domain are held fixed independently of the source label.')])
